values
('vocab_monetary','monetary','adjective','related to money or financial value','[{"senseId":"monetary_1","meaning":"related to money or financial value","acceptedParaphrases":["financial","money-related"],"masteryContexts":[{"contextId":"u1_31_monetary_meaning","text":"The trophy has little monetary value, but it means a great deal to the winners.","meaning":"connected with money or payment","wrongMeanings":["linked to the history of an object","related to how rare something is","connected with the size of a prize"]},{"contextId":"u1_31_monetary_paraphrase","text":"Volunteers receive no monetary reward for helping at the tournament, only a free t-shirt.","meaning":"involving money or other financial value","wrongMeanings":["involving public praise or thanks","relating to physical effort or strength","concerning the time given freely"]}],"situationDistractors":["The winner received a medal and a certificate.","The team was given a new kit by the school.","The best player was invited to train with the national squad.","The runners enjoyed a free meal after the race."],"gapDistractors":[{"contextId":"u1_31_monetary_gap_meaning_sentence","answer":"monetary","wrong":["military","mandatory","medical"]},{"contextId":"u1_31_monetary_gap_x1","answer":"monetary","wrong":["mandatory","momentary","mental"]},{"contextId":"u1_31_monetary_gap_x2","answer":"monetary","wrong":["mandatory","military","medical"]}],"spellingErrors":["monatary","monetery","monitary","monetory","monnetary","monitery"],"masteryPassages":[{"passageId":"u1_31_monetary_passage_1","contextId":"u1_31_monetary_gap_meaning_sentence","text":"Nobody wins a fortune in this competition. The prize has little ____ value, but the winner keeps a famous trophy that has been passed down for a hundred years.","answer":"monetary"},{"passageId":"u1_31_monetary_passage_2","contextId":"u1_31_monetary_gap_x1","text":"The charity asked volunteers for their time. Any ____ gifts, however small, were also gratefully received.","answer":"monetary"}],"contextDependentParaphrases":[],"wrongParaphrases":["physical","political","environmental"],"misleadingDistractors":["physical","historic","personal"]}]'::jsonb,'[]'::jsonb,'["monetary value","monetary reward"]'::jsonb,'live'),
('vocab_estimated','estimated','adjective','calculated or judged approximately rather than known exactly','[{"senseId":"estimated_1","meaning":"calculated or judged approximately rather than known exactly","acceptedParaphrases":["approximate","roughly calculated"],"masteryContexts":[{"contextId":"u1_32_estimated_meaning","text":"The estimated crowd at the final was fifty thousand, though officials admitted that nobody had counted exactly.","meaning":"worked out approximately, not exactly","wrongMeanings":["counted exactly at the stadium gates","announced in advance by the organisers","taken from the final match report"]},{"contextId":"u1_32_estimated_paraphrase","text":"The estimated cost of the new stadium is two hundred million pounds, but the final bill may be higher.","meaning":"based on calculation rather than certainty","wrongMeanings":["agreed in a signed contract","paid in full by the club","reduced after long talks with the builders"]}],"situationDistractors":["Her club published the exact score of the match.","The referee confirmed the final result after the video check.","Officials counted every spectator at the gate.","The shop announced the fixed price of the new boots.","After checking the timings, the judges confirmed the final result of the race.","Officials counted every spectator at the gate, and they published the exact total the next morning.","The referee blew his whistle exactly at four to start the second half.","Several parents volunteered to drive the younger players to the distant stadium.","Their coach travelled to the neighbouring town early in the morning."],"gapDistractors":[{"contextId":"u1_32_estimated_gap_meaning_sentence","answer":"estimated","wrong":["rejected","forgotten","cancelled"]},{"contextId":"u1_32_estimated_gap_x1","answer":"estimated","wrong":["rejected","forgotten","cancelled"]},{"contextId":"u1_32_estimated_gap_x2","answer":"estimated","wrong":["unnecessary","overdue","ancient"]}],"spellingErrors":["estamated","estimeted","estemated","estimatd","esstimated","estimmated"],"wordFamilyForms":[{"form":"estimated","partOfSpeech":"adjective","example":"The estimated attendance was ten thousand people.","pedagogicallyUseful":true},{"form":"estimate","partOfSpeech":"verb","example":"Can you estimate how long the journey will take?","pedagogicallyUseful":true},{"form":"estimation","partOfSpeech":"noun","example":"In my estimation, the team played better than last week.","pedagogicallyUseful":true},{"form":"underestimate","partOfSpeech":"verb","example":"Never underestimate the importance of a good warm-up.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u1_32_estimated_passage_1","contextId":"u1_32_estimated_gap_meaning_sentence","text":"The bridge has been closed for a month. The ____ cost of repairing it is two million pounds, although the engineers will not know the exact figure until they open it up.","answer":"estimated"},{"passageId":"u1_32_estimated_passage_2","contextId":"u1_32_estimated_gap_x1","text":"Nobody counted the crowd at the parade. The ____ number of people who watched was around forty thousand.","answer":"estimated"}],"contextDependentParaphrases":[],"wrongParaphrases":["confirmed","exact","unforgettable"],"misleadingDistractors":["confirmed","exact","historic"]}]'::jsonb,'["estimate","estimation","underestimate"]'::jsonb,'["estimated cost","estimated number"]'::jsonb,'live'),
('vocab_struggle','struggle','verb','to have difficulty doing or achieving something','[{"senseId":"struggle_1","meaning":"to have difficulty doing or achieving something","acceptedParaphrases":["have difficulty","find it hard"],"masteryContexts":[{"contextId":"u1_33_struggle_meaning","text":"Some beginners struggle to maintain their balance on the board.","meaning":"have great difficulty doing something","wrongMeanings":["enjoy trying something new for fun","refuse to follow the instructor’s advice","wait patiently for others to finish"]},{"contextId":"u1_33_struggle_paraphrase","text":"A new player often struggles to control the ball at first.","meaning":"need much effort because something is hard","wrongMeanings":["lose interest in a game very quickly","refuse to share the ball with others","quarrel about the rules with a friendly teammate"]}],"situationDistractors":["The beginners learned to ride the bikes easily on the first day.","She refused to try the difficult climb.","The new player scored two goals in his first match.","His coach gave the team an easy exercise to finish.","The class finished the long run so easily that the teacher added extra laps.","Experienced climbers found the short route very simple, and they reached the summit within minutes.","The local athletes trained happily together every weekend and rarely missed a session.","The sports shop on the high street sells running shoes at reduced prices."],"gapDistractors":[{"contextId":"u1_33_struggle_gap_base_inf","answer":"struggle","wrong":["avoid","finish","practise"]},{"contextId":"u1_33_struggle_gap_third_inf","answer":"struggles","wrong":["avoids","finishes","practises"]},{"contextId":"u1_33_struggle_gap_past_inf","answer":"struggled","wrong":["avoided","finished","practised"]},{"contextId":"u1_33_struggle_gap_perfect_with","answer":"struggled","wrong":["argued","chatted","negotiated"]},{"contextId":"u1_33_struggle_gap_third_with","answer":"struggles","wrong":["argues","chats","negotiates"]}],"spellingErrors":["strugle","struggel","strugel","struggal","strugal","struggol"],"masteryPassages":[{"passageId":"u1_33_struggle_passage_1","contextId":"u1_33_struggle_gap_base_inf","text":"Essay writing is difficult for many learners. Many students ____ with it at first, but it becomes easier with regular practice and clear feedback.","answer":"struggle"},{"passageId":"u1_33_struggle_passage_2","contextId":"u1_33_struggle_gap_third_inf","text":"The old car reached the bottom of the steep hill and began to climb. It ____ up the slope, making a loud noise, and for a moment it seemed that it might roll backwards.","answer":"struggled"}],"contextDependentParaphrases":[],"wrongParaphrases":["succeed easily","finish early","make steady progress"],"misleadingDistractors":["succeed easily","permit","recommend"],"grammarForms":{"base":"struggle","thirdPerson":"struggles","past":"struggled","pastParticiple":"struggled","ing":"struggling"},"grammarPatterns":["struggle + to-infinitive","struggle with + noun"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_minimum','minimum','noun','the smallest amount, number, or level allowed or needed','[{"senseId":"minimum_1","meaning":"the smallest amount, number, or level allowed or needed","acceptedParaphrases":["lowest amount","least"],"masteryContexts":[{"contextId":"u1_34_minimum_meaning","text":"Players must complete a minimum of three training sessions each week.","meaning":"lowest acceptable amount or level","wrongMeanings":["highest amount that is permitted","average amount for most players","usual amount offered to beginners"]},{"contextId":"u1_34_minimum_paraphrase","text":"The minimum age for competitors is sixteen.","meaning":"smallest quantity that meets a requirement","wrongMeanings":["greatest age allowed for entry","most common age among competitors","age when players usually retire from sport"]}],"situationDistractors":["The ride has a maximum height limit of two metres.","The average age of the players is sixteen.","The club expects around thirty players to come.","The highest score in the league is ninety points.","The stadium holds sixty thousand people when every single seat has been sold.","The prize for the race winner is far higher than the prizes for the other finalists.","The cup final tickets sold out surprisingly quickly, within a few minutes.","Volunteers painted the changing rooms during the long summer holidays.","The captain led the team onto the pitch before the opening whistle."],"gapDistractors":[{"contextId":"u1_34_minimum_gap_meaning_sentence","answer":"minimum","wrong":["handful","mixture","section"]},{"contextId":"u1_34_minimum_gap_x1","answer":"minimum","wrong":["maximum","average","tallest"]},{"contextId":"u1_34_minimum_gap_x2","answer":"minimum","wrong":["maximum","couple","handful"]}],"spellingErrors":["minimun","minumum","minimom","minimium","miniumum","minnimum"],"wordFamilyForms":[{"form":"minimum","partOfSpeech":"noun","example":"You need a minimum of two hours of practice a week.","pedagogicallyUseful":true},{"form":"minimal","partOfSpeech":"adjective","example":"The injury caused only minimal damage, so she could play again soon.","pedagogicallyUseful":true,"altExample":"The damage to the pitch was minimal, so the final went ahead as planned."},{"form":"minimise","partOfSpeech":"verb","example":"Wearing the right shoes helps to minimise the risk of injury.","pedagogicallyUseful":true,"altExample":"Warming up properly helps athletes to minimise the risk of injury."}],"masteryPassages":[{"passageId":"u1_34_minimum_passage_1","contextId":"u1_34_minimum_gap_meaning_sentence","text":"To pass the course, students must attend a ____ of eighty per cent of the lessons. Anyone below that figure must repeat the year.","answer":"minimum"},{"passageId":"u1_34_minimum_passage_2","contextId":"u1_34_minimum_gap_x1","text":"Wages cannot legally fall below a certain level. In many countries this ____ wage is set by the government each year.","answer":"minimum"}],"contextDependentParaphrases":[],"wrongParaphrases":["highest amount","usual amount","exact amount"],"misleadingDistractors":["maximum","average","estimate"],"teacherNote":"Often paraphrased structurally as at least rather than by a direct noun synonym."}]'::jsonb,'["minimal","minimise"]'::jsonb,'["minimum age","minimum requirement"]'::jsonb,'live'),
('vocab_championship','championship','noun','a major competition that decides the best player or team','[{"senseId":"championship_1","meaning":"a major competition that decides the best player or team","acceptedParaphrases":["title competition","major contest"],"masteryContexts":[{"contextId":"u1_35_championship_meaning","text":"She qualified for the national championship after winning the regional event.","meaning":"major contest deciding the title winner","wrongMeanings":["small match played to practise skills","series of lessons for gifted young players","trophy given for good behaviour"]},{"contextId":"u1_35_championship_paraphrase","text":"He trained all year for the championship.","meaning":"competition that determines the leading player","wrongMeanings":["course designed to improve fitness","friendly game between two old school rivals","season ticket for loyal supporters"]}],"situationDistractors":["Their class played a friendly game on a weekday afternoon.","The coach held a short practice for new players.","Two schools played one match to test a new pitch.","Our team travelled abroad for a training holiday.","Every week, the club holds a relaxed practice session for members of every age and ability.","The two schools played a friendly match to raise money for the new library.","Neighbouring villages organise a friendly cricket match every summer to raise money.","Local residents complained about the noise from the open-air concert last summer."],"gapDistractors":[{"contextId":"u1_35_championship_gap_meaning_sentence","answer":"championship","wrong":["coach","whistle","stadium"]},{"contextId":"u1_35_championship_gap_x1","answer":"championship","wrong":["referee","trainer","whistle"]},{"contextId":"u1_35_championship_gap_x2","answer":"championship","wrong":["whistle","injury","trainer"]}],"spellingErrors":["champianship","champeonship","championshp","championsip","champonship","championchip"],"masteryPassages":[{"passageId":"u1_35_championship_passage_1","contextId":"u1_35_championship_gap_meaning_sentence","text":"The team practised twice a day for months. They hoped to win the ____ and bring the cup back to the school.","answer":"championship"},{"passageId":"u1_35_championship_passage_2","contextId":"u1_35_championship_gap_x1","text":"Over three days, the best gymnasts in the country take part. The winner of the national ____ is invited to join the squad.","answer":"championship"}],"contextDependentParaphrases":[],"wrongParaphrases":["friendly match","school lesson","annual team meeting"],"misleadingDistractors":["practice session","friendly match","lesson"]}]'::jsonb,'[]'::jsonb,'["national championship","win the championship"]'::jsonb,'live'),
('vocab_competitor','competitor','noun','a person or organisation taking part in a competition','[{"senseId":"competitor_1","meaning":"a person or organisation taking part in a competition","acceptedParaphrases":["contestant","participant in a competition"],"masteryContexts":[{"contextId":"u1_36_competitor_meaning","text":"Each competitor must register before the race begins.","meaning":"person taking part in a contest","wrongMeanings":["person watching a match closely","person employed to help a team","person who rules on a decision"]},{"contextId":"u1_36_competitor_paraphrase","text":"As the youngest competitor in the race, she was expected to finish last, but she came fourth.","meaning":"person entered in a race to win","wrongMeanings":["person who sells tickets for the race","person who times each runner","person who announces the race results"]}],"situationDistractors":["A fan cheered loudly from the stands.","The official checked the stopwatch at the finish line.","The coach made a speech to the team before the game.","A volunteer handed out water at the finish line.","Hundreds of supporters waited outside the stadium to watch the team arrive.","At the end of the event, the head teacher presented certificates to all of the volunteers.","The marathon route passes through the old town and along the river.","The local newspaper published photographs of the celebrations the next morning.","Their school choir performed two songs before the match began."],"gapDistractors":[{"contextId":"u1_36_competitor_gap_meaning_sentence","answer":"competitor","wrong":["trophy","stopwatch","commentator"]},{"contextId":"u1_36_competitor_gap_x1","answer":"competitor","wrong":["spectator","referee","commentator"]},{"contextId":"u1_36_competitor_gap_x2","answer":"competitor","wrong":["trophy","stopwatch","commentator"]}],"spellingErrors":["competator","competiter","competetor","compeditor","competitar","compettitor"],"wordFamilyForms":[{"form":"competitor","partOfSpeech":"noun","example":"Every competitor must wear a number during the race.","pedagogicallyUseful":true},{"form":"compete","partOfSpeech":"verb","example":"Over two hundred students compete in the school sports day.","pedagogicallyUseful":true},{"form":"competition","partOfSpeech":"noun","example":"The competition begins at nine o’clock tomorrow.","pedagogicallyUseful":true},{"form":"competitive","partOfSpeech":"adjective","example":"Professional football is a highly competitive career.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u1_36_competitor_passage_1","contextId":"u1_36_competitor_gap_meaning_sentence","text":"The marathon was about to begin. At the start of the race, each ____ received a number to pin on the front of their shirt.","answer":"competitor"},{"passageId":"u1_36_competitor_passage_2","contextId":"u1_36_competitor_gap_x1","text":"Sales at the bakery fell sharply last spring. A new ____ had opened across the road and began selling bread at a lower price.","answer":"competitor"}],"contextDependentParaphrases":[],"wrongParaphrases":["spectator","commentator","organiser"],"misleadingDistractors":["spectator","coach","organiser"]}]'::jsonb,'["compete","competition","competitive"]'::jsonb,'["strong competitor","fellow competitor"]'::jsonb,'live'),
('vocab_relatively','relatively','adverb','to a fairly limited degree when compared with something else','[{"senseId":"relatively_1","meaning":"to a fairly limited degree when compared with something else","acceptedParaphrases":["comparatively","fairly"],"masteryContexts":[{"contextId":"u1_37_relatively_meaning","text":"The new sports centre is relatively small, with room for only two courts.","meaning":"to a degree judged by comparison","wrongMeanings":["to a very high degree","in a way that avoids all comparison","without any change over time"]},{"contextId":"u1_37_relatively_paraphrase","text":"The route is relatively easy compared with the mountain course.","meaning":"to a fair degree, judged against another","wrongMeanings":["more than anyone could expect","to the highest possible degree every time","only for a short time"]}],"situationDistractors":["The new sports centre is exactly the same size as the old one.","The new sports centre is enormous and has a huge pool.","The new sports centre will open next month.","The new sports centre was built in only six weeks.","Nobody could believe how enormous the new stadium looked inside.","The match started at exactly three o’clock on the school field on the last day of term.","Heavy snow is forecast across the entire region for the whole weekend.","Before the match began yesterday, journalists interviewed several famous footballers outside the stadium."],"gapDistractors":[{"contextId":"u1_37_relatively_gap_meaning_sentence","answer":"relatively","wrong":["exactly","hardly","surprisingly"]},{"contextId":"u1_37_relatively_gap_x1","answer":"relatively","wrong":["exactly","hardly","recently"]},{"contextId":"u1_37_relatively_gap_x2","answer":"relatively","wrong":["annually","instantly","permanently"]}],"spellingErrors":["relativly","relatevely","relativelly","realatively","relativley","relitively"],"masteryPassages":[{"passageId":"u1_37_relatively_passage_1","contextId":"u1_37_relatively_gap_meaning_sentence","text":"Most of the class finished the test early. It was ____ easy, although a few students still made careless mistakes.","answer":"relatively"},{"passageId":"u1_37_relatively_passage_2","contextId":"u1_37_relatively_gap_x1","text":"The village shop is the only place to buy food within ten kilometres. Prices there are ____ high, but people accept it.","answer":"relatively"}],"contextDependentParaphrases":[],"wrongParaphrases":["completely","exactly","internationally"],"misleadingDistractors":["completely","extremely","exactly"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_patience','patience','noun','the ability to remain calm while waiting or dealing with difficulty','[{"senseId":"patience_1","meaning":"the ability to remain calm while waiting or dealing with difficulty","acceptedParaphrases":["ability to wait calmly","calm persistence"],"masteryContexts":[{"contextId":"u1_38_patience_meaning","text":"Learning a difficult skill takes patience and regular practice.","meaning":"ability to stay calm while waiting","wrongMeanings":["strong wish to succeed very quickly","natural talent for learning skills","careful choice of the right equipment"]},{"contextId":"u1_38_patience_paraphrase","text":"Coaching young beginners requires patience.","meaning":"calm persistence despite difficulty","wrongMeanings":["great physical strength and fitness","detailed knowledge of the rules","a loud voice and strong opinions"]}],"situationDistractors":["Her coach shouted at the players for making mistakes.","He gave up after the first failed attempt.","She hurried through the lesson to finish early.","The players were bored and kept checking the clock.","Our coach rushed every drill to save time."],"gapDistractors":[{"contextId":"u1_38_patience_gap_meaning_sentence","answer":"patience","wrong":["laziness","anger","boredom"]},{"contextId":"u1_38_patience_gap_x1","answer":"patience","wrong":["luggage","height","distance"]},{"contextId":"u1_38_patience_gap_x2","answer":"patience","wrong":["noise","violence","hurry"]}],"spellingErrors":["patients","pasience","patiense","paitence","patiance","pateince"],"wordFamilyForms":[{"form":"patience","partOfSpeech":"noun","example":"Teaching beginners requires a great deal of patience.","pedagogicallyUseful":true},{"form":"patient","partOfSpeech":"adjective","example":"Be patient with yourself while you learn a new skill.","pedagogicallyUseful":true},{"form":"patiently","partOfSpeech":"adverb","example":"The fans waited patiently for the gates to open.","pedagogicallyUseful":true},{"form":"impatient","partOfSpeech":"adjective","example":"He grew impatient when the match kept being delayed.","pedagogicallyUseful":true}],"masteryPassages":[{"passageId":"u1_38_patience_passage_1","contextId":"u1_38_patience_gap_meaning_sentence","text":"Fishing is a quiet hobby. It needs a great deal of ____: you may sit by the river for hours before anything bites.","answer":"patience"},{"passageId":"u1_38_patience_passage_2","contextId":"u1_38_patience_gap_x1","text":"The customer shouted at the assistant, but she answered calmly and kindly. Her ____ impressed everyone who was waiting in the queue.","answer":"patience"}],"contextDependentParaphrases":[],"wrongParaphrases":["strong dislike of waiting","fast speed of progress","physical strength to continue"],"misleadingDistractors":["courage","strength","speed"]}]'::jsonb,'["patient","patiently","impatient"]'::jsonb,'["show patience","require patience"]'::jsonb,'live'),
('vocab_atmosphere','atmosphere','noun','the feeling or mood created in a place or situation','[{"senseId":"atmosphere_1","meaning":"the feeling or mood created in a place or situation","acceptedParaphrases":["mood","feeling"],"masteryContexts":[{"contextId":"u1_39_atmosphere_meaning","text":"The crowd created an exciting atmosphere before the match.","meaning":"overall mood felt in a place","wrongMeanings":["noise level measured near the pitch","number of fans who watch a match","weather conditions at the start of play"]},{"contextId":"u1_39_atmosphere_paraphrase","text":"Music and cheering created a positive atmosphere in the stadium.","meaning":"emotional feeling created by a setting","wrongMeanings":["warm air produced inside a large building","shape of the stadium seating area","space available for fans in the stadium"]}],"situationDistractors":["The temperature of the hall was too high for training.","The match started at four o''clock in the afternoon.","The stadium was empty and the seats were new.","The tickets for the final sold out in an hour.","The stadium sold out within minutes, so the club doubled the seating.","Tickets for the final cost twice as much as for the earlier rounds, which surprised many fans.","The ticket office closes at five, so latecomers must buy tickets online.","The stadium announcer read out the team lists very carefully."],"gapDistractors":[{"contextId":"u1_39_atmosphere_gap_meaning_sentence","answer":"atmosphere","wrong":["temperature","scoreboard","timetable"]},{"contextId":"u1_39_atmosphere_gap_x1","answer":"atmosphere","wrong":["scoreboard","timetable","trophy"]},{"contextId":"u1_39_atmosphere_gap_x2","answer":"atmosphere","wrong":["scoreboard","timetable","uniform"]}],"spellingErrors":["atmosfere","atmospher","atmoshpere","athmosphere","atmosphear","atmosphire"],"masteryPassages":[{"passageId":"u1_39_atmosphere_passage_1","contextId":"u1_39_atmosphere_gap_meaning_sentence","text":"The concert hall was full of laughter and music. The warm ____ made even the shyest guests feel welcome.","answer":"atmosphere"},{"passageId":"u1_39_atmosphere_passage_2","contextId":"u1_39_atmosphere_gap_x1","text":"Before the exam, the room was silent and tense. You could feel the nervous ____ as soon as you opened the door.","answer":"atmosphere"}],"contextDependentParaphrases":[],"wrongParaphrases":["fee","schedule","audience"],"misleadingDistractors":["temperature","schedule","audience"]}]'::jsonb,'[]'::jsonb,'["friendly atmosphere","create an atmosphere"]'::jsonb,'live'),
('vocab_incredible','incredible','adjective','extremely impressive, surprising, or difficult to believe','[{"senseId":"incredible_1","meaning":"extremely impressive, surprising, or difficult to believe","acceptedParaphrases":["amazing","extraordinary"],"masteryContexts":[{"contextId":"u1_40_incredible_meaning","text":"Her final lap was incredible and broke the school record.","meaning":"very impressive and quite surprising","wrongMeanings":["quite slow but still acceptable","very hard to measure by hand","just good enough to be noticed"]},{"contextId":"u1_40_incredible_paraphrase","text":"The goalkeeper made an incredible save in the final seconds.","meaning":"exceptionally remarkable and hard to believe","wrongMeanings":["very careless and likely to cost goals","fairly ordinary for an experienced professional","too late to change the final result"]}],"situationDistractors":["His goalkeeper made a routine save in the first minute.","Her time was close to the average for the race.","The match ended in a boring nil-nil draw.","The result was exactly what everyone had expected.","The match finished as a boring nil-nil draw that nobody will remember.","Her time in the race was rather slow, so she felt a little disappointed afterwards.","The final score was exactly what every supporter had expected beforehand."],"gapDistractors":[{"contextId":"u1_40_incredible_gap_meaning_sentence","answer":"incredible","wrong":["slow","ordinary","disappointing"]},{"contextId":"u1_40_incredible_gap_x1","answer":"incredible","wrong":["annual","empty","unremarkable"]},{"contextId":"u1_40_incredible_gap_x2","answer":"incredible","wrong":["slow","expensive","predictable"]}],"spellingErrors":["incredable","increadible","incredibal","incridible","incrediable","increedible"],"masteryPassages":[{"passageId":"u1_40_incredible_passage_1","contextId":"u1_40_incredible_gap_meaning_sentence","text":"The view from the top of the tower was ____. We could see the whole city, the river and the mountains beyond.","answer":"incredible"},{"passageId":"u1_40_incredible_passage_2","contextId":"u1_40_incredible_gap_x1","text":"The old man ran a marathon on his ninetieth birthday. It sounds ____, but he finished in under six hours.","answer":"incredible"}],"contextDependentParaphrases":[],"wrongParaphrases":["ordinary","boring","unlikely"],"misleadingDistractors":["ordinary","predictable","minor"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live')
